1	import { useState } from 'react';
2	import { useMutation, useQueryClient } from '@tanstack/react-query';
3	import { clientsKey, createClient, isValidEmail } from './queries';
4	
5	// Add a client. useState holds only what the user is currently typing (CLAUDE.md rule 4); the write
6	// is a mutation that invalidates ['clients'] so the list refreshes itself — no hand-maintained list.
7	// Email is required and must be well-formed: we block the write client-side (and the server enforces
8	// the same rule) so a bad address can never be saved.
9	export function ClientForm() {
10	  const [name, setName] = useState('');
11	  const [email, setEmail] = useState('');
12	  const [emailError, setEmailError] = useState(false);
13	  const queryClient = useQueryClient();
14	
15	  const mutation = useMutation({
16	    mutationFn: createClient,
17	    onSuccess: () => {
18	      void queryClient.invalidateQueries({ queryKey: clientsKey });
19	      setName('');
20	      setEmail('');
21	    },
22	    onError: () => {
23	      // Server rejected the address (defence in depth) — surface the same error anchor.
24	      setEmailError(true);
25	    },
26	  });
27	
28	  return (
29	    <form
30	      data-testid="client-form"
31	      onSubmit={(event) => {
32	        event.preventDefault();
33	        if (!isValidEmail(email)) {
34	          setEmailError(true);
35	          return;
36	        }
37	        setEmailError(false);
38	        mutation.mutate({ name, email });
39	      }}
40	    >
41	      <input
42	        data-testid="client-form-name"
43	        placeholder="Name"
44	        value={name}
45	        onChange={(event) => setName(event.target.value)}
46	      />
47	      <input
48	        data-testid="client-form-email"
49	        placeholder="Email"
50	        value={email}
51	        onChange={(event) => {
52	          setEmail(event.target.value);
53	          if (emailError) {
54	            setEmailError(false);
55	          }
56	        }}
57	      />
58	      {emailError && (
59	        <p data-testid="client-form-email-error" role="alert">
60	          Enter a valid email address.
61	        </p>
62	      )}
63	      <button data-testid="client-form-submit" type="submit">
64	        Add client
65	      </button>
66	    </form>
67	  );
68	}
