3	import java.math.BigDecimal;
4	import net.officefloor.server.http.HttpException;
5	import net.officefloor.server.http.HttpStatus;
6	import net.officefloor.web.HttpPathParameter;
7	import net.officefloor.web.ObjectResponse;
8	import org.springframework.web.bind.annotation.RequestBody;
9	
10	/**
11	 * POST /api/invoices/{id}/lineitems/{lineItemId} — change one line on an invoice from
12	 * {description, qty, unitPrice} and return the saved row. Wired by
13	 * {@code officefloor/rest/api/invoices/{id}/lineitems/{lineItemId}.POST.yml}. Same validation as
14	 * adding a line: a description, a whole quantity above zero and a unit price above zero; anything
15	 * missing/invalid is rejected with 400, an unknown invoice or line with 404, and a line that does
16	 * not belong to the named invoice likewise with 404. The invoice's stored amount is kept in step as
17	 * the sum of its lines' qty * unitPrice, so every view that shows the amount stays correct.
18	 */
19	public class InvoiceLineItemUpdate {
20	
21	    public void service(@HttpPathParameter("id") String id,
22	            @HttpPathParameter("lineItemId") String lineItemId, @RequestBody NewLineItem body,
23	            InvoiceRepository invoices, LineItemRepository lineItems,
24	            ObjectResponse<LineItem> response) {
25	        Long invoiceId = Long.valueOf(id);
26	        Long lineId = Long.valueOf(lineItemId);
27	        Invoice invoice = invoices.findById(invoiceId)
28	                .orElseThrow(() -> new HttpException(HttpStatus.NOT_FOUND));
29	        LineItem line = lineItems.findById(lineId)
30	                .orElseThrow(() -> new HttpException(HttpStatus.NOT_FOUND));
31	        if (!invoiceId.equals(line.getInvoiceId())) {
32	            throw new HttpException(HttpStatus.NOT_FOUND);
33	        }
34	        String description = body.getDescription();
35	        Integer qty = body.getQty();
36	        BigDecimal unitPrice = body.getUnitPrice();
37	        if (description == null || description.isBlank() || qty == null || qty <= 0
38	                || unitPrice == null || unitPrice.signum() <= 0) {
39	            throw new HttpException(HttpStatus.BAD_REQUEST);
40	        }
41	        line.setDescription(description.trim());
42	        line.setQty(qty);
43	        line.setUnitPrice(unitPrice);
44	        LineItem saved = lineItems.save(line);
45	
46	        // Keep the invoice's stored amount in step with its lines: amount = sum(qty * unitPrice).
47	        BigDecimal total = BigDecimal.ZERO;
48	        for (LineItem l : lineItems.findByInvoiceIdOrderByIdAsc(invoiceId)) {
49	            total = total.add(l.getUnitPrice().multiply(BigDecimal.valueOf(l.getQty())));
50	        }
51	        invoice.setAmount(total);
52	        invoices.save(invoice);
53	
54	        response.send(saved);
55	    }
56	}
57

